SET FOREIGN_KEY_CHECKS=0;

-- ----------------------------
-- Table structure for api
-- ----------------------------
DROP TABLE IF EXISTS `api`;
CREATE TABLE `api` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(255) CHARACTER SET utf8mb4 DEFAULT NULL,
  `api` longtext CHARACTER SET utf8mb4,
  `create_time` datetime DEFAULT NULL,
  `type` int(1) DEFAULT '-1' COMMENT '0：文生图；1文生视频；2图生视频；3首尾帧',
  `tags` varchar(255) CHARACTER SET utf8mb4 DEFAULT NULL,
  `is_default` int(1) DEFAULT '0' COMMENT '是否为默认api,每一个类型的api只有一个默认',
  `outputs_num` varchar(255) DEFAULT NULL,
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `start_words` text,
  `end_words` text,
  `class_type` int(1) DEFAULT '0',
  `workflow_id` varchar(255) DEFAULT NULL,
  `img_num` int(11) DEFAULT '0',
  `audio_num` int(11) DEFAULT '0',
  `vedio_num` int(11) DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1062 DEFAULT CHARSET=utf8;

