-- ----------------------------
-- Table structure for task
-- ----------------------------
DROP TABLE IF EXISTS `task`;
CREATE TABLE `task` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `task_name` varchar(255) CHARACTER SET utf8mb4 DEFAULT NULL,
  `client_id` varchar(255) DEFAULT NULL,
  `type` int(11) DEFAULT '0' COMMENT '0:图片；1:视频',
  `prompt` longtext CHARACTER SET utf8mb4,
  `url` varchar(255) DEFAULT NULL,
  `create_time` timestamp NULL DEFAULT NULL,
  `task_id` varchar(255) DEFAULT NULL,
  `ori_ip` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of task
-- ----------------------------

-- ----------------------------
-- Table structure for task_records
-- ----------------------------
DROP TABLE IF EXISTS `task_records`;
CREATE TABLE `task_records` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `type` int(11) DEFAULT '0' COMMENT '0 图片 1 文生视频 2 图生视频',
  `task_list` longtext,
  `create_time` datetime DEFAULT NULL,
  `task_name` varchar(255) CHARACTER SET utf8mb4 DEFAULT NULL,
  `ori_ip` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

