-- Records of task_records
-- ----------------------------

-- ----------------------------
-- View structure for task_c
-- ----------------------------
DROP VIEW IF EXISTS `task_c`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`%` SQL SECURITY DEFINER VIEW `task_c` AS select distinct `task`.`task_id` AS `task_id`,`task`.`task_name` AS `task_name`,`task`.`type` AS `type`,`task`.`create_time` AS `create_time` from `task` ;

-- ----------------------------
-- Function structure for regexp_replace
-- ----------------------------
DROP FUNCTION IF EXISTS `regexp_replace`;
DELIMITER ;;
CREATE DEFINER=`root`@`%` FUNCTION `regexp_replace`(string_a VARCHAR(1000), pattern VARCHAR(1000), string_b VARCHAR(1000)) RETURNS varchar(1000) CHARSET utf8
    DETERMINISTIC
BEGIN
    DECLARE string_c VARCHAR(1000);
    DECLARE nub VARCHAR(1);
    DECLARE i INT;
    SET i = 1;
    SET string_c = '';
    IF string_a REGEXP pattern THEN
        loop_label: LOOP
            IF i > CHAR_LENGTH(string_a) THEN
                LEAVE loop_label;
            END IF;
            SET nub = SUBSTRING(string_a, i, 1);
            IF NOT nub REGEXP pattern THEN
                SET string_c = CONCAT(string_c, nub);
            ELSE
                SET string_c = CONCAT(string_c, string_b);
            END IF;
            SET i = i + 1;
        END LOOP;
    ELSE
        SET string_c = string_a;
    END IF;
    RETURN string_c;
END
;;
DELIMITER ;
